import { Router, type Request, type Response } from "express";
import { getAllDevices, getDeviceById, updateDeviceState } from "../db/devices-table";
import { getSchedules } from "../db/schedules-table";

export const router = Router();

router.post("/run-scheduled-rules", async (req: Request, res: Response) => {
  const currentTimestamp = new Date().toISOString();
  const schedules = getSchedules().filter(schedule => schedule.trigger_time <= currentTimestamp);

  for (const schedule of schedules) {
    const device = getDeviceById(schedule.device_id.toString());
    if (device) {
      updateDeviceState(device.id, schedule.action);
    }
  }

  res.status(200).send({ message: "Scheduled rules executed." });
});

